<script lang="ts">import type { PageProps } from './$types'; let { data, form }: PageProps = $props();</script><main class="page-shell community-page"><header><p class="eyebrow">Community</p><h1>Inbox</h1></header>{#if form?.message}<p class="community-notice">{form.message}</p>{/if}<form method="POST" action="?/read" class="community-card">{#each data.inbox as item}<label class="community-row"><input type="checkbox" name="id" value={item.id} checked={!item.readAt}/><strong>{item.kind}</strong><span>{JSON.stringify(item.payload)}</span><small>{item.createdAt}</small></label>{:else}<p>Your community inbox is quiet.</p>{/each}<button>Mark selected as read</button></form></main>
